[metadata] {"type": "create", "filePath": "/app/output/final_report.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>EV Charging Network Performance &amp; Grid Optimization Report</title>
<script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.4/dist/chart.umd.min.js"></script>
<style>
  :root {
    --primary: #1a73e8;
    --primary-light: #4a9af5;
    --primary-dark: #0d47a1;
    --accent: #00c853;
    --accent-warm: #ff6d00;
    --danger: #d32f2f;
    --bg: #f0f2f5;
    --card-bg: #ffffff;
    --text: #202124;
    --text-secondary: #5f6368;
    --border: #dadce0;
    --shadow: 0 1px 3px rgba(60,64,67,0.12), 0 1px 2px rgba(60,64,67,0.08);
    --shadow-lg: 0 4px 12px rgba(60,64,67,0.15), 0 2px 6px rgba(60,64,67,0.1);
    --radius: 8px;
  }
  * { margin:0; padding:0; box-sizing:border-box; }
  body {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, sans-serif;
    background: var(--bg);
    color: var(--text);
    line-height: 1.6;
  }
  .report-wrap { max-width: 1280px; margin: 0 auto; padding: 24px 16px 60px; }

  /* Header */
  .report-header {
    background: linear-gradient(135deg, var(--primary-dark) 0%, var(--primary) 60%, var(--primary-light) 100%);
    color: #fff;
    border-radius: var(--radius);
    padding: 36px 40px 28px;
    margin-bottom: 24px;
    box-shadow: var(--shadow-lg);
  }
  .report-header h1 { font-size: 1.7rem; font-weight: 700; margin-bottom: 6px; }
  .report-header .subtitle { font-size: 0.95rem; opacity: 0.88; margin-bottom: 14px; }
  .report-header .meta { font-size: 0.82rem; opacity: 0.72; }

  /* Navigation */
  .nav-bar {
    background: var(--card-bg);
    border-radius: var(--radius);
    padding: 10px 20px;
    margin-bottom: 24px;
    box-shadow: var(--shadow);
    display: flex;
    flex-wrap: wrap;
    gap: 6px;
    align-items: center;
  }
  .nav-bar a {
    font-size: 0.82rem;
    text-decoration: none;
    color: var(--primary);
    padding: 5px 12px;
    border-radius: 4px;
    transition: background 0.15s;
    white-space: nowrap;
  }
  .nav-bar a:hover { background: #e8f0fe; }
  .nav-label { font-size: 0.72rem; text-transform: uppercase; letter-spacing: 0.06em; color: var(--text-secondary); font-weight: 600; margin-right: 6px; }

  /* KPI Banner */
  .kpi-banner {
    display: grid;
    grid-template-columns: repeat(5, 1fr);
    gap: 14px;
    margin-bottom: 28px;
  }
  @media (max-width: 900px) { .kpi-banner { grid-template-columns: repeat(3, 1fr); } }
  @media (max-width: 600px) { .kpi-banner { grid-template-columns: repeat(2, 1fr); } }
  .kpi-card {
    background: var(--card-bg);
    border-radius: var(--radius);
    padding: 20px 18px 16px;
    box-shadow: var(--shadow);
    border-top: 3px solid var(--primary);
    position: relative;
  }
  .kpi-card .kpi-label { font-size: 0.75rem; text-transform: uppercase; letter-spacing: 0.04em; color: var(--text-secondary); font-weight: 600; margin-bottom: 6px; }
  .kpi-card .kpi-value { font-size: 1.65rem; font-weight: 700; color: var(--text); }
  .kpi-card .kpi-sub { font-size: 0.78rem; color: var(--text-secondary); margin-top: 4px; }
  .kpi-card.accent { border-top-color: var(--accent); }
  .kpi-card.warn { border-top-color: var(--accent-warm); }
  .kpi-card.danger { border-top-color: var(--danger); }

  /* Section */
  .section {
    background: var(--card-bg);
    border-radius: var(--radius);
    box-shadow: var(--shadow);
    margin-bottom: 24px;
    padding: 28px 32px 24px;
  }
  .section h2 {
    font-size: 1.2rem;
    font-weight: 700;
    color: var(--primary-dark);
    margin-bottom: 6px;
    display: flex;
    align-items: center;
    gap: 8px;
  }
  .section h2 .sec-num {
    background: var(--primary);
    color: #fff;
    width: 28px; height: 28px;
    border-radius: 50%;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    font-size: 0.8rem;
    font-weight: 700;
    flex-shrink: 0;
  }
  .section .sec-obj { font-size: 0.88rem; color: var(--text-secondary); margin-bottom: 20px; }

  /* Chart containers */
  .chart-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 20px; margin: 20px 0; }
  @media (max-width: 800px) { .chart-grid { grid-template-columns: 1fr; } }
  .chart-box {
    background: #fafbfc;
    border: 1px solid var(--border);
    border-radius: var(--radius);
    padding: 16px;
  }
  .chart-box h4 { font-size: 0.85rem; font-weight: 600; color: var(--text-secondary); margin-bottom: 10px; text-transform: uppercase; letter-spacing: 0.03em; }
  .chart-full { grid-column: 1 / -1; }

  /* Tables */
  .data-table { width: 100%; border-collapse: collapse; margin: 14px 0; font-size: 0.85rem; }
  .data-table th { background: #f1f3f4; color: var(--text-secondary); font-weight: 600; text-align: left; padding: 9px 12px; border-bottom: 2px solid var(--border); text-transform: uppercase; font-size: 0.75rem; letter-spacing: 0.04em; }
  .data-table td { padding: 8px 12px; border-bottom: 1px solid #f0f0f0; }
  .data-table tr:hover { background: #f8f9fa; }
  .data-table .num { text-align: right; font-variant-numeric: tabular-nums; }

  /* Takeaway box */
  .takeaway {
    background: #e8f5e9;
    border-left: 4px solid var(--accent);
    border-radius: 0 var(--radius) var(--radius) 0;
    padding: 14px 18px;
    margin: 18px 0 0;
    font-size: 0.88rem;
    color: #1b5e20;
  }
  .takeaway strong { display: block; margin-bottom: 4px; font-size: 0.8rem; text-transform: uppercase; letter-spacing: 0.04em; }

  /* Badge */
  .badge { display: inline-block; padding: 2px 10px; border-radius: 10px; font-size: 0.76rem; font-weight: 600; }
  .badge-green { background: #c8e6c9; color: #2e7d32; }
  .badge-yellow { background: #fff3e0; color: #e65100; }
  .badge-red { background: #ffcdd2; color: #c62828; }

  /* Insight list */
  .insight-list { list-style: none; padding: 0; margin: 14px 0; }
  .insight-list li { padding: 8px 0 8px 24px; position: relative; font-size: 0.9rem; }
  .insight-list li::before { content: ''; position: absolute; left: 0; top: 14px; width: 8px; height: 8px; border-radius: 50%; background: var(--primary); }
  .insight-list li.warn::before { background: var(--accent-warm); }
  .insight-list li.good::before { background: var(--accent); }
  .insight-list li.bad::before { background: var(--danger); }

  /* Recommendation cards */
  .rec-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(280px, 1fr)); gap: 16px; margin: 18px 0; }
  .rec-card {
    background: #f8f9fa;
    border: 1px solid var(--border);
    border-radius: var(--radius);
    padding: 18px;
    border-top: 3px solid var(--primary);
  }
  .rec-card.high { border-top-color: var(--accent-warm); }
  .rec-card.medium { border-top-color: var(--primary); }
  .rec-card.low { border-top-color: var(--accent); }
  .rec-card .rec-title { font-weight: 700; font-size: 0.95rem; margin-bottom: 6px; }
  .rec-card .rec-body { font-size: 0.85rem; color: var(--text-secondary); }
  .rec-card .rec-impact { margin-top: 8px; font-size: 0.8rem; font-weight: 600; }

  /* Footer */
  .report-footer {
    text-align: center;
    font-size: 0.78rem;
    color: var(--text-secondary);
    padding: 24px 0;
  }

  canvas { max-height: 320px; }
</style>
</head>
<body>
<div class="report-wrap">

  <!-- HEADER -->
  <header class="report-header">
    <h1>EV Charging Network Performance &amp; Grid Optimization</h1>
    <div class="subtitle">Analytics Report &mdash; Infrastructure Operations &amp; Smart-Grid Insights</div>
    <div class="meta">Dataset: 8,354 sessions &middot; Jan 2025 &ndash; ongoing &middot; 20 stations &middot; Generated May 21, 2026</div>
  </header>

  <!-- NAVIGATION -->
  <nav class="nav-bar">
    <span class="nav-label">Jump to</span>
    <a href="#station-utilization">Station Utilization</a>
    <a href="#queue-wait">Queue &amp; Wait</a>
    <a href="#energy-grid">Energy &amp; Grid</a>
    <a href="#renewable-pricing">Renewable &amp; Pricing</a>
    <a href="#vehicle-behavior">Vehicle Behavior</a>
    <a href="#optimization">Recommendations</a>
  </nav>

  <!-- KPI BANNER -->
  <div class="kpi-banner">
    <div class="kpi-card">
      <div class="kpi-label">Avg Waiting Time</div>
      <div class="kpi-value">9.53 <span style="font-size:0.55em;font-weight:400">min</span></div>
